function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-70, 100, 140);
  ctx.fill();
  ctx.stroke();

  // Draw stick figure reading book
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2-100, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+20);
  ctx.lineTo(W/2-100, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+30);
  ctx.lineTo(W/2-120, H/2+40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+30);
  ctx.lineTo(W/2-80, H/2+40);
  ctx.stroke();

  // Draw wisdom sparks
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2-100+Math.sin(t+i)*20, H/2-30+Math.cos(t+i)*20, 5, 0, 2*Math.PI);
    ctx.fill();
  }

  // Draw lesson text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1666', W/2, H/2+100+Math.sin(t)*10);

  ctx.restore();
}
